function uniqueLabels(values) {
  if (!Array.isArray(values)) {
    throw new TypeError('values must be an array of strings');
  }

  for (let i = 0; i < values.length; i++) {
    if (typeof values[i] !== 'string') {
      throw new TypeError('values must contain only strings');
    }
  }

  const seen = new Set();
  const result = [];

  for (const value of values) {
    const label = value.trim();
    if (label === '' || seen.has(label)) continue;
    seen.add(label);
    result.push(label);
  }

  return result;
}

// Basic trimming, empty removal, and first-occurrence deduplication
assert.deepStrictEqual(
  uniqueLabels(['  alpha  ', 'beta', '', '   ', 'alpha', ' beta ']),
  ['alpha', 'beta']
);

