assert.deepStrictEqual(
  uniqueLabels(['A', 'a', 'A']),
  ['A', 'a']
);

// Empty input
assert.deepStrictEqual(uniqueLabels([]), []);

// Does not mutate the input
const input = ['  x  ', 'x', '', ' y ', 'x'];
const inputCopy = input.slice();
assert.deepStrictEqual(uniqueLabels(input), ['x', 'y']);
assert.deepStrictEqual(input, inputCopy);

// Rejects non-arrays
assert.throws(() => uniqueLabels('not an array'), TypeError);
assert.throws(() => uniqueLabels(null), TypeError);

// Rejects arrays containing non-strings, including sparse arrays
assert.throws(() => uniqueLabels(['ok', 1]), TypeError);
assert.throws(() => uniqueLabels([, 'x']), TypeError);
