/**
 * Returns a unique array of trimmed, non-empty strings.
 * @param {string[]} values
 * @returns {string[]}
 */
function uniqueLabels(values) {
  if (!Array.isArray(values) || !values.every(v => typeof v === 'string')) {
    throw new TypeError('Input must be an array of strings');
  }

  const processed = values
    .map(s => s.trim())
    .filter(s => s.length > 0);

  return [...new Set(processed)];
}

// Tests
try {
  // Test basic functionality and deduplication
  assert.deepEqual(
    uniqueLabels([' apple ', 'banana', ' apple', ' ', 'banana ']), 
    ['apple', 'banana']
  );

  // Test empty strings and whitespace-only strings
  assert.deepEqual(
    uniqueLabels(['', '   ', '\n\t']), 
    []
  );

  // Test preservation of first occurrence
  assert.deepEqual(
    uniqueLabels(['A', 'B', 'A']), 
    ['A', 'B']
  );

  // Test non-mutation of input
  const input = [' a ', ' b '];
  uniqueLabels(input);
  assert.deepEqual(input, [' a ', ' b ']);

  // Test type validation
  assert.throws(() => uniqueLabels(null), TypeError);
  assert.throws(() => uniqueLabels([1, 2]), TypeError);
  assert.throws(() => uniqueLabels(['a', null]), TypeError);

  console.log('All tests passed.');
} catch (err) {
  console.error('Test failed:', err);
  process.exit(1);
}
